// src/pages/DashboardProf.jsx
import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import './DashboardProf.css';

function DashboardProf() {
  const [user, setUser] = useState({});
  const [stats, setStats] = useState({
    totalCours: 0,
    etudiantsInscrits: 0,
    evaluations: 0,
    moyenneGenerale: 0
  });
  const [recentCours, setRecentCours] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    const fetchData = async () => {
      const token = localStorage.getItem('token');
      if (!token) {
        navigate('/login');
        return;
      }

      try {
        const [userRes, statsRes, coursRes] = await Promise.all([
          axios.get('http://localhost:5000/api/profs/me', {
            headers: { Authorization: `Bearer ${token}` }
          }),
          axios.get('http://localhost:5000/api/profs/stats', {
            headers: { Authorization: `Bearer ${token}` }
          }),
          axios.get('http://localhost:5000/api/profs/cours/recent', {
            headers: { Authorization: `Bearer ${token}` }
          })
        ]);

        setUser(userRes.data);
        setStats(statsRes.data);
        setRecentCours(coursRes.data);
      } catch (err) {
        console.error(err);
        if (err.response?.status === 401) {
          localStorage.removeItem('token');
          navigate('/login');
        } else {
          alert('Erreur lors du chargement des données');
        }
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, [navigate]);

  const handleLogout = () => {
    localStorage.removeItem('token');
    navigate('/login');
  };

  if (isLoading) {
    return (
      <div className="dashboard-loading">
        <div className="loading-spinner"></div>
        <p>Chargement de votre espace...</p>
      </div>
    );
  }

  return (
    <div className="dashboard-prof">
      {/* Header */}
      <header className="dashboard-header">
        <div className="header-content">
          <div className="welcome-section">
            <h1>Bonjour, Professeur {user.nom} 👨‍🏫</h1>
            <p>Bienvenue dans votre espace d'enseignement</p>
          </div>
          <div className="header-actions">
            <button className="profile-btn">
              <span className="user-avatar">
                {user.nom?.charAt(0).toUpperCase()}
              </span>
              Mon Profil
            </button>
            <button onClick={handleLogout} className="logout-btn">
              Déconnexion
            </button>
          </div>
        </div>
      </header>

      <div className="dashboard-content">
        {/* Statistiques */}
        <section className="stats-section">
          <h2>Vue d'ensemble</h2>
          <div className="stats-grid">
            <div className="stat-card">
              <div className="stat-icon cours-icon">📚</div>
              <div className="stat-info">
                <h3>{stats.totalCours}</h3>
                <p>Cours créés</p>
              </div>
            </div>
            
            <div className="stat-card">
              <div className="stat-icon students-icon">👥</div>
              <div className="stat-info">
                <h3>{stats.etudiantsInscrits}</h3>
                <p>Étudiants inscrits</p>
              </div>
            </div>
            
            <div className="stat-card">
              <div className="stat-icon eval-icon">📊</div>
              <div className="stat-info">
                <h3>{stats.evaluations}</h3>
                <p>Évaluations</p>
              </div>
            </div>
            
            <div className="stat-card">
              <div className="stat-icon avg-icon">⭐</div>
              <div className="stat-info">
                <h3>{stats.moyenneGenerale}/20</h3>
                <p>Moyenne générale</p>
              </div>
            </div>
          </div>
        </section>

        <div className="dashboard-main">
          {/* Cours récents */}
          <section className="recent-cours-section">
            <div className="section-header">
              <h2>Cours récents</h2>
              <button className="primary-btn">+ Nouveau cours</button>
            </div>
            
            <div className="cours-grid">
              {recentCours.length > 0 ? (
                recentCours.map((cours) => (
                  <div key={cours._id} className="cours-card">
                    <div className="cours-header">
                      <h3>{cours.titre}</h3>
                      <span className={`status-badge ${cours.statut}`}>
                        {cours.statut}
                      </span>
                    </div>
                    <p className="cours-description">{cours.description}</p>
                    <div className="cours-meta">
                      <span className="meta-item">
                        👥 {cours.etudiantsInscrits} étudiants
                      </span>
                      <span className="meta-item">
                        📅 {new Date(cours.dateCreation).toLocaleDateString()}
                      </span>
                    </div>
                    <div className="cours-actions">
                      <button className="action-btn view-btn">Voir</button>
                      <button className="action-btn edit-btn">Modifier</button>
                    </div>
                  </div>
                ))
              ) : (
                <div className="empty-state">
                  <div className="empty-icon">📚</div>
                  <h3>Aucun cours créé</h3>
                  <p>Commencez par créer votre premier cours</p>
                  <button className="primary-btn">Créer un cours</button>
                </div>
              )}
            </div>
          </section>

          {/* Sidebar */}
          <aside className="dashboard-sidebar">
            {/* Actions rapides */}
            <div className="sidebar-card">
              <h3>Actions rapides</h3>
              <div className="quick-actions">
                <button className="quick-action-btn">
                  <span className="action-icon">➕</span>
                  Nouveau cours
                </button>
                <button className="quick-action-btn">
                  <span className="action-icon">📝</span>
                  Créer évaluation
                </button>
                <button className="quick-action-btn">
                  <span className="action-icon">👥</span>
                  Gérer étudiants
                </button>
                <button className="quick-action-btn">
                  <span className="action-icon">📊</span>
                  Voir statistiques
                </button>
              </div>
            </div>

            {/* Prochaines échéances */}
            <div className="sidebar-card">
              <h3>Prochaines échéances</h3>
              <div className="deadlines-list">
                <div className="deadline-item">
                  <div className="deadline-info">
                    <strong>Examen Mathématiques</strong>
                    <span>15 Dec 2024</span>
                  </div>
                  <span className="deadline-badge urgent">Urgent</span>
                </div>
                <div className="deadline-item">
                  <div className="deadline-info">
                    <strong>Projet Physique</strong>
                    <span>20 Dec 2024</span>
                  </div>
                  <span className="deadline-badge warning">À venir</span>
                </div>
              </div>
            </div>

            {/* Informations profil */}
            <div className="sidebar-card profile-info">
              <h3>Informations profil</h3>
              <div className="profile-details">
                <div className="profile-item">
                  <span className="label">Nom:</span>
                  <span className="value">{user.nom}</span>
                </div>
                <div className="profile-item">
                  <span className="label">Email:</span>
                  <span className="value">{user.email}</span>
                </div>
                <div className="profile-item">
                  <span className="label">Membre depuis:</span>
                  <span className="value">Jan 2024</span>
                </div>
              </div>
            </div>
          </aside>
        </div>
      </div>
    </div>
  );
}

export default DashboardProf;
